content:
Below is a reusable Terraform module for the requested S3, RDS PostgreSQL, and IAM service-account role. It supports isolated `dev`/`prod` workspaces and adds production S3 cross-region replication to `us-west-2`.

The module assumes the VPC, private subnets, and EKS OIDC provider already exist.

## Layout

```text
terraform/
├── modules/
│   └── app-infra/
│       ├── main.tf
│       ├── variables.tf
│       └── outputs.tf
├── environments/
│   ├── dev.tfvars
│   └── prod.tfvars
├── main.tf
├── variables.tf
├── outputs.tf
├── versions.tf
└── backend.tf
```

## `modules/app-infra/variables.tf`

```hcl
variable "name" {
  description = "Application name used in resource names and tags."
  type        = string
}

variable "environment" {
  description = "Deployment environment."
  type        = string

  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "environment must be either dev or prod."
  }
}

variable "vpc_id" {
  description = "VPC in which the RDS instance is created."
  type        = string
}

variable "database_subnet_ids" {
  description = "Private subnet IDs for the RDS subnet group."
  type        = list(string)

  validation {
    condition     = length(var.database_subnet_ids) >= 2
    error_message = "At least two database subnet IDs are required."
  }
}

variable "database_client_security_group_ids" {
  description = "Security groups allowed to connect to PostgreSQL."
  type        = list(string)
  default     = []
}

variable "database_name" {
  description = "Initial PostgreSQL database name."
  type        = string
  default     = "app"
}

variable "database_username" {
  description = "PostgreSQL master username. Password is managed by RDS in Secrets Manager."
  type        = string
  default     = "app_admin"
}

variable "database_instance_class" {
  description = "RDS instance class."
  type        = string
}

variable "database_allocated_storage" {
  description = "Initial RDS storage in GiB."
  type        = number
  default     = 20
}

variable "database_max_allocated_storage" {
  description = "Maximum storage autoscaling limit in GiB."
  type        = number
  default     = 100
}

variable "database_multi_az" {
  description = "Whether RDS is deployed across multiple availability zones."
  type        = bool
}

variable "database_backup_retention_period" {
  description = "RDS automated backup retention in days."
  type        = number
  default     = 7

  validation {
    condition     = var.database_backup_retention_period >= 7
    error_message = "Database backup retention must be at least 7 days."
  }
}

variable "oidc_provider_arn" {
  description = "ARN of the EKS IAM OIDC provider."
  type        = string
}

variable "oidc_provider_url" {
  description = "EKS OIDC issuer URL, with or without the https:// prefix."
  type        = string
}

variable "service_account_namespace" {
  description = "Kubernetes namespace containing the service account."
  type        = string
  default     = "default"
}

variable "service_account_name" {
  description = "Kubernetes service account that may assume the IAM role."
  type        = string
  default     = "app"
}

variable "replication_region" {
  description = "AWS region for the production replica bucket."
  type        = string
  default     = "us-west-2"
}

variable "tags" {
  description = "Additional resource tags."
  type        = map(string)
  default     = {}
}
```

## `modules/app-infra/main.tf`

```hcl
terraform {
  required_version = ">= 1.6.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"

      configuration_aliases = [
        aws.replica
      ]
    }
  }
}

data "aws_caller_identity" "current" {}

locals {
  resource_prefix = "${var.name}-${var.environment}"
  bucket_name = lower(
    "${var.name}-${var.environment}-${data.aws_caller_identity.current.account_id}"
  )

  replication_enabled = var.environment == "prod"
  oidc_issuer          = trimsuffix(trimprefix(var.oidc_provider_url, "https://"), "/")

  common_tags = merge(
    {
      Application = var.name
      Environment = var.environment
      ManagedBy   = "Terraform"
    },
    var.tags
  )
}

# -----------------------------------------------------------------------------
# Primary S3 bucket
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "assets" {
  bucket = local.bucket_name

  tags = merge(local.common_tags, {
    Name = "${local.resource_prefix}-assets"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "assets" {
  bucket = aws_s3_bucket.assets.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "assets" {
  bucket = aws_s3_bucket.assets.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "assets" {
  bucket = aws_s3_bucket.assets.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "assets" {
  bucket = aws_s3_bucket.assets.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

# -----------------------------------------------------------------------------
# Production cross-region replication bucket
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "replica" {
  count    = local.replication_enabled ? 1 : 0
  provider = aws.replica

  bucket = "${local.bucket_name}-${var.replication_region}"

  tags = merge(local.common_tags, {
    Name = "${local.resource_prefix}-assets-replica"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "replica" {
  count    = local.replication_enabled ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  count    = local.replication_enabled ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  count    = local.replication_enabled ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "replica" {
  count    = local.replication_enabled ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

data "aws_iam_policy_document" "replication_assume_role" {
  count = local.replication_enabled ? 1 : 0

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "replication" {
  count = local.replication_enabled ? 1 : 0

  name               = "${local.resource_prefix}-s3-replication"
  assume_role_policy = data.aws_iam_policy_document.replication_assume_role[0].json
  tags               = local.common_tags
}

data "aws_iam_policy_document" "replication" {
  count = local.replication_enabled ? 1 : 0

  statement {
    sid = "ReadSourceBucket"

    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket"
    ]

    resources = [aws_s3_bucket.assets.arn]
  }

  statement {
    sid = "ReadSourceVersions"

    actions = [
      "s3:GetObjectVersion",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionTagging"
    ]

    resources = ["${aws_s3_bucket.assets.arn}/*"]
  }

  statement {
    sid = "WriteReplicaVersions"

    actions = [
      "s3:ReplicateDelete",
      "s3:ReplicateObject",
      "s3:ReplicateTags"
    ]

    resources = ["${aws_s3_bucket.replica[0].arn}/*"]
  }
}

resource "aws_iam_role_policy" "replication" {
  count = local.replication_enabled ? 1 : 0

  name   = "${local.resource_prefix}-s3-replication"
  role   = aws_iam_role.replication[0].id
  policy = data.aws_iam_policy_document.replication[0].json
}

resource "aws_s3_bucket_replication_configuration" "assets" {
  count = local.replication_enabled ? 1 : 0

  bucket = aws_s3_bucket.assets.id
  role   = aws_iam_role.replication[0].arn

  rule {
    id     = "replicate-to-${var.replication_region}"
    status = "Enabled"

    filter {}

    destination {
      bucket        = aws_s3_bucket.replica[0].arn
      storage_class = "STANDARD"
    }

    delete_marker_replication {
      status = "Enabled"
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.assets,
    aws_s3_bucket_versioning.replica,
    aws_iam_role_policy.replication
  ]
}

# -----------------------------------------------------------------------------
# RDS PostgreSQL
# -----------------------------------------------------------------------------

resource "aws_db_subnet_group" "database" {
  name       = "${local.resource_prefix}-database"
  subnet_ids = var.database_subnet_ids

  tags = merge(local.common_tags, {
    Name = "${local.resource_prefix}-database"
  })
}

resource "aws_security_group" "database" {
  name_prefix = "${local.resource_prefix}-database-"
  description = "PostgreSQL access for ${local.resource_prefix}"
  vpc_id      = var.vpc_id

  egress {
    description = "No application-initiated egress required"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["127.0.0.1/32"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.resource_prefix}-database"
  })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_vpc_security_group_ingress_rule" "database" {
  for_each = toset(var.database_client_security_group_ids)

  security_group_id            = aws_security_group.database.id
  referenced_security_group_id = each.value
  ip_protocol                  = "tcp"
  from_port                    = 5432
  to_port                      = 5432

  description = "PostgreSQL from application security group"
}

resource "aws_db_instance" "database" {
  identifier = "${local.resource_prefix}-postgres"

  engine         = "postgres"
  instance_class = var.database_instance_class

  db_name  = var.database_name
  username = var.database_username
  port     = 5432

  manage_master_user_password = true

  allocated_storage     = var.database_allocated_storage
  max_allocated_storage = var.database_max_allocated_storage
  storage_type          = "gp3"
  storage_encrypted     = true

  multi_az            = var.database_multi_az
  publicly_accessible = false

  db_subnet_group_name   = aws_db_subnet_group.database.name
  vpc_security_group_ids = [aws_security_group.database.id]

  backup_retention_period = var.database_backup_retention_period
  backup_window           = "03:00-04:00"
  maintenance_window      = "sun:04:00-sun:05:00"

  deletion_protection = true
  skip_final_snapshot = true

  auto_minor_version_upgrade = true
  copy_tags_to_snapshot       = true

  enabled_cloudwatch_logs_exports = ["postgresql", "upgrade"]

  tags = merge(local.common_tags, {
    Name = "${local.resource_prefix}-postgres"
  })
}

# -----------------------------------------------------------------------------
# EKS service-account IAM role
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "service_account_assume_role" {
  statement {
    sid     = "AllowEksServiceAccount"
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [var.oidc_provider_arn]
    }

    condition {
      test     = "StringEquals"
      variable = "${local.oidc_issuer}:aud"
      values   = ["sts.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "${local.oidc_issuer}:sub"
      values = [
        "system:serviceaccount:${var.service_account_namespace}:${var.service_account_name}"
      ]
    }
  }
}

resource "aws_iam_role" "service_account" {
  name               = "${local.resource_prefix}-service-account"
  assume_role_policy = data.aws_iam_policy_document.service_account_assume_role.json

  tags = local.common_tags
}

data "aws_iam_policy_document" "service_account" {
  statement {
    sid = "ListAssets"

    actions = [
      "s3:GetBucketLocation",
      "s3:ListBucket"
    ]

    resources = [aws_s3_bucket.assets.arn]
  }

  statement {
    sid = "ManageApplicationAssets"

    actions = [
      "s3:AbortMultipartUpload",
      "s3:DeleteObject",
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:ListMultipartUploadParts",
      "s3:PutObject"
    ]

    resources = ["${aws_s3_bucket.assets.arn}/*"]
  }

  statement {
    sid = "ReadDatabaseCredentials"

    actions = [
      "secretsmanager:DescribeSecret",
      "secretsmanager:GetSecretValue"
    ]

    resources = [
      aws_db_instance.database.master_user_secret[0].secret_arn
    ]
  }
}

resource "aws_iam_role_policy" "service_account" {
  name   = "${local.resource_prefix}-application-access"
  role   = aws_iam_role.service_account.id
  policy = data.aws_iam_policy_document.service_account.json
}
```

## `modules/app-infra/outputs.tf`

```hcl
output "bucket_name" {
  description = "Primary application assets bucket name."
  value       = aws_s3_bucket.assets.id
}

output "bucket_arn" {
  description = "Primary application assets bucket ARN."
  value       = aws_s3_bucket.assets.arn
}

output "replica_bucket_name" {
  description = "Production replica bucket name, or null in dev."
  value       = try(aws_s3_bucket.replica[0].id, null)
}

output "database_address" {
  description = "RDS PostgreSQL hostname."
  value       = aws_db_instance.database.address
}

output "database_port" {
  description = "RDS PostgreSQL port."
  value       = aws_db_instance.database.port
}

output "database_name" {
  description = "Initial PostgreSQL database name."
  value       = aws_db_instance.database.db_name
}

output "database_secret_arn" {
  description = "Secrets Manager ARN containing the RDS-managed master credentials."
  value       = aws_db_instance.database.master_user_secret[0].secret_arn
}

output "database_security_group_id" {
  description = "RDS security group ID."
  value       = aws_security_group.database.id
}

output "service_account_role_arn" {
  description = "IAM role ARN for the Kubernetes service account."
  value       = aws_iam_role.service_account.arn
}
```

# Root configuration

## `versions.tf`

```hcl
terraform {
  required_version = ">= 1.6.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}
```

## `backend.tf`

Use a remote backend so workspace state is isolated and encrypted.

```hcl
terraform {
  backend "s3" {
    bucket         = "replace-with-terraform-state-bucket"
    key            = "app-infra/terraform.tfstate"
    region         = "us-east-1"
    encrypt        = true
    dynamodb_table = "terraform-state-locks"
  }
}
```

With the S3 backend, non-default workspaces are stored under distinct workspace state paths.

## `variables.tf`

```hcl
variable "environment" {
  type = string

  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "environment must be dev or prod."
  }
}

variable "primary_region" {
  type = string
}

variable "vpc_id" {
  type = string
}

variable "database_subnet_ids" {
  type = list(string)
}

variable "application_security_group_ids" {
  type = list(string)
}

variable "database_instance_class" {
  type = string
}

variable "database_multi_az" {
  type = bool
}

variable "oidc_provider_arn" {
  type = string
}

variable "oidc_provider_url" {
  type = string
}

variable "service_account_namespace" {
  type    = string
  default = "app"
}

variable "service_account_name" {
  type    = string
  default = "web"
}
```

## `main.tf`

```hcl
provider "aws" {
  region = var.primary_region

  default_tags {
    tags = {
      Project     = "stateless-web-app"
      Environment = var.environment
      ManagedBy   = "Terraform"
    }
  }
}

provider "aws" {
  alias  = "replica"
  region = "us-west-2"

  default_tags {
    tags = {
      Project     = "stateless-web-app"
      Environment = var.environment
      ManagedBy   = "Terraform"
    }
  }
}

module "app_infra" {
  source = "./modules/app-infra"

  providers = {
    aws         = aws
    aws.replica = aws.replica
  }

  name        = "webapp"
  environment = var.environment

  vpc_id                             = var.vpc_id
  database_subnet_ids                = var.database_subnet_ids
  database_client_security_group_ids = var.application_security_group_ids

  database_instance_class = var.database_instance_class
  database_multi_az        = var.database_multi_az

  oidc_provider_arn         = var.oidc_provider_arn
  oidc_provider_url         = var.oidc_provider_url
  service_account_namespace = var.service_account_namespace
  service_account_name      = var.service_account_name

  tags = {
    Owner = "platform-team"
  }

  lifecycle {
    precondition {
      condition     = terraform.workspace == var.environment
      error_message = "Terraform workspace must match the environment variable."
    }
  }
}
```

