# Environment variables

## `environments/dev.tfvars`

```hcl
environment    = "dev"
primary_region = "us-east-1"

vpc_id = "vpc-REPLACE_DEV"

database_subnet_ids = [
  "subnet-REPLACE_DEV_A",
  "subnet-REPLACE_DEV_B"
]

application_security_group_ids = [
  "sg-REPLACE_DEV_EKS_APP"
]

database_instance_class = "db.t3.micro"
database_multi_az        = false

oidc_provider_arn = "arn:aws:iam::123456789012:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/REPLACE_DEV"
oidc_provider_url = "https://oidc.eks.us-east-1.amazonaws.com/id/REPLACE_DEV"

service_account_namespace = "app"
service_account_name      = "web"
```

